<script setup>
import { content } from '../../data/content'
import { brandName, siteConfig, navigation } from '../../data/site'
import { contactLink } from '../../utils/contact'
</script>
<template><footer class="site-footer"><div class="container"><div class="footer-top"><RouterLink to="/" class="brand"><span class="brand-mark">{{ siteConfig.brandMark }}</span><span>{{ brandName }}<small>{{ siteConfig.tagline }}</small></span></RouterLink><p>{{ content.footer.textStart }}<br>{{ content.footer.textEnd }}</p><nav :aria-label="content.footer.navigationLabel"><RouterLink v-for="item in navigation.filter(i => i.footer !== false)" :key="item.to" :to="item.to">{{ item.label }}</RouterLink></nav><div class="footer-social"><a v-if="contactLink(null, 'telegram')" :href="contactLink(null, 'telegram')">{{ content.footer.telegramLabel }}</a><span v-else>{{ content.footer.telegramPending }}</span><a v-if="contactLink(null, 'vk')" :href="contactLink(null, 'vk')">{{ content.footer.vkLabel }}</a><span v-else>{{ content.footer.vkPending }}</span><a v-if="contactLink(null, 'phone')" :href="contactLink(null, 'phone')">{{ siteConfig.phone }}</a><span v-else>{{ content.footer.phonePending }}</span><a v-if="contactLink(null, 'max')" :href="contactLink(null, 'max')">{{ content.contacts.maxLabel }} ↗</a><a v-if="contactLink(null, 'email')" :href="contactLink(null, 'email')">{{ siteConfig.email }}</a></div></div><div class="footer-bottom"><span>© {{ new Date().getFullYear() }} {{ brandName }}{{ content.footer.copyright }}</span><RouterLink :to="content.footer.privacyTo">{{ content.footer.privacy }}</RouterLink></div></div></footer></template>